import AVFoundation
import Observation

/// Vault's voice: pre-recorded lines in Resources/Voice (generated by scripts/voice-lines.sh).
/// A line plays when its step appears and stops when the user moves on. A missing file just means silence,
/// so the app works before the recordings exist.
@MainActor
@Observable
final class Voice {
    static let shared = Voice()

    /// True while a line is playing; the mascot animates while it is.
    private(set) var speaking = false

    @ObservationIgnored private var player: AVAudioPlayer?
    @ObservationIgnored private let finish = FinishDelegate()

    private init() {
        finish.onFinish = { [weak self] in Task { @MainActor in self?.speaking = false } }
    }

    /// Plays the first recording that exists, e.g. `["onb-goal-digital_products", "onb-goal"]`.
    func play(_ names: [String], muted: Bool) {
        stop()
        guard !muted, let url = names.lazy.compactMap({ Bundle.main.url(forResource: $0, withExtension: "m4a") }).first else { return }
        do {
            // Plays alongside the user's music instead of stopping it, and respects the silent switch.
            try AVAudioSession.sharedInstance().setCategory(.ambient, mode: .spokenAudio, options: [.mixWithOthers])
            try AVAudioSession.sharedInstance().setActive(true)
            let p = try AVAudioPlayer(contentsOf: url)
            p.delegate = finish
            p.prepareToPlay()
            p.play()
            player = p
            speaking = true
        } catch {
            speaking = false
        }
    }

    func stop() {
        player?.stop()
        player = nil
        speaking = false
    }
}

private final class FinishDelegate: NSObject, AVAudioPlayerDelegate {
    var onFinish: (() -> Void)?
    func audioPlayerDidFinishPlaying(_ player: AVAudioPlayer, successfully flag: Bool) { onFinish?() }
}
